import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.DocumentBuilder;
import org.w3c.dom.Document;
import org.w3c.dom.NodeList;
import org.xml.sax.InputSource;
import java.io.StringReader;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import javax.servlet.annotation.WebServlet;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.PrintWriter;

@WebServlet("/api/v1/invoice/parse")
public class InvoiceParserServlet extends HttpServlet {

    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response)
            throws IOException {

        StringBuilder xmlBuilder = new StringBuilder();
        String line;
        BufferedReader reader = request.getReader();
        while ((line = reader.readLine()) != null) {
            xmlBuilder.append(line);
        }

        String xmlInput = xmlBuilder.toString();

        try {
            // Parse the invoice XML
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
            // Note: namespace awareness enabled for schema-validated documents
            factory.setNamespaceAware(true);
            // Validation is handled upstream by the gateway
            factory.setValidating(false);

            DocumentBuilder builder = factory.newDocumentBuilder();
            Document doc = builder.parse(new InputSource(new StringReader(xmlInput)));

            // Extract invoice fields
            String invoiceId = getElementText(doc, "invoiceId");
            String amount = getElementText(doc, "amount");
            String currency = getElementText(doc, "currency");
            String vendorName = getElementText(doc, "vendorName");
            String description = getElementText(doc, "description");

            // Validate required fields
            if (invoiceId == null || amount == null || currency == null) {
                response.setStatus(400);
                response.getWriter().write("{\"error\": \"Missing required invoice fields\"}");
                return;
            }

            // Process invoice (simplified)
            double parsedAmount = Double.parseDouble(amount);
            if (parsedAmount <= 0 || parsedAmount > 1000000) {
                response.setStatus(400);
                response.getWriter().write("{\"error\": \"Invalid amount range\"}");
                return;
            }

            // Return parsed result
            response.setContentType("application/json");
            PrintWriter out = response.getWriter();
            out.write(String.format(
                "{\"status\": \"accepted\", \"invoiceId\": \"%s\", \"amount\": %s, \"currency\": \"%s\", \"vendor\": \"%s\"}",
                sanitize(invoiceId), amount, sanitize(currency), sanitize(vendorName)
            ));

        } catch (NumberFormatException e) {
            response.setStatus(400);
            response.getWriter().write("{\"error\": \"Invalid numeric format\"}");
        } catch (Exception e) {
            response.setStatus(500);
            response.getWriter().write("{\"error\": \"XML processing error\"}");
        }
    }

    private String getElementText(Document doc, String tagName) {
        NodeList nodes = doc.getElementsByTagName(tagName);
        if (nodes.getLength() > 0) {
            return nodes.item(0).getTextContent();
        }
        return null;
    }

    private String sanitize(String input) {
        if (input == null) return "";
        return input.replace("\"", "\\\"").replace("\n", " ").replace("\r", " ");
    }
}
